import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { uploadFilesWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await uploadFilesWorkflow(req.scope)
    .run({
      input: {
        files: [{
          filename: "test.jpg",
          mimeType: "img/jpg",
          content: "base64-string",
          access: "public"
        }]
      }
    })

  res.send(result)
}

